/**
 * Verify an RS256 JWT against the JWKS and return its claims, or throw an Error whose message is the first failed
 * check: 'malformed token' (not three parts), 'unexpected algorithm' (anything but RS256, HS256 included),
 * 'unknown key' (no JWK with the header's kid), 'bad signature', 'expired' (exp not a number, or now >= exp + 30),
 * 'wrong issuer', 'wrong audience' (aud is a string or a list).
 */
export function verifyJwt(token: string, jwks: { keys: Jwk[] }, opts: { issuer: string; audience: string; now: number }): Claims {
  throw new Error('Not implemented');
}

